INSERT INTO `events` VALUES ('3ff579e6-56b4-46cb-a6c5-7b1c73b2e6d1','aae8308e-1a8c-4495-9c44-01bee32c8f3c','Business Talk: Naik Kelas dengan Halal','business-talk-naik-kelas-dengan-halal','Seminar','Strategi branding dan perluasan pasar UMKM halal bersama praktisi dan mentor bisnis Bandung.','Gedung Creative Center, Bandung','2026-03-07 02:00:00.000','2026-03-07 05:00:00.000',NULL,'published','2026-11-05 14:48:28.335','2026-11-05 14:48:28.335'),('76e006b1-93fa-45d5-95e8-d2fa4775713f','aae8308e-1a8c-4495-9c44-01bee32c8f3c','Workshop Self Declare untuk UMKM','workshop-self-declare-umkm','Pelatihan','Praktik mengisi aplikasi SIHALAL, menyiapkan dokumen, dan memahami kriteria self declare gratis.','Sekretariat KHB, Bandung','2026-01-24 02:00:00.000','2026-01-24 08:00:00.000',NULL,'published','2026-11-05 14:48:28.335','2026-11-05 14:48:28.335'),('af191f1f-0342-4db5-893a-119ebd1b451b','aae8308e-1a8c-4495-9c44-01bee32c8f3c','Halal Fest Bandung 2026','halal-fest-bandung-2026','Festival','Pameran produk halal UMKM Bandung, talkshow sertifikasi, dan konsultasi gratis bersama pendamping halal KHB.','Balai Kota Bandung, Jawa Barat','2026-02-14 01:00:00.000','2026-02-15 10:00:00.000',NULL,'published','2026-11-05 14:48:28.335','2026-11-05 14:48:28.335'),('e9a2f3c0-57d2-4207-b0d7-d71259fc03ce','aae8308e-1a8c-4495-9c44-01bee32c8f3c','Pendampingan PPH Batch 12','pendampingan-pph-batch-12','Pendampingan','Pendampingan proses produk halal bersama PPH KHB: verifikasi dokumen sampai sidang fatwa.','Online (Zoom)','2026-01-10 06:00:00.000','2026-01-10 09:00:00.000',NULL,'published','2026-11-05 14:48:28.335','2026-11-05 14:48:28.335');
