INSERT INTO `flow_nodes` VALUES ('0a877ca7-c819-41a6-b105-8a142d29a67c','aae8308e-1a8c-4495-9c44-01bee32c8f3c','question','Apa itu layanan UMKM Klinik?','Program pendampingan UMKM KHB untuk pembinaan produk halal dan legalitas usaha.',5,1,'2026-11-05 14:48:28.297','2026-11-05 14:48:28.297',608,216),('7bed391b-315c-4ff5-ae60-0f5054a223da','aae8308e-1a8c-4495-9c44-01bee32c8f3c','question','Bagaimana cara mendaftar sertifikasi halal?','Alur enam langkah KHB: pendaftaran, pendampingan PPH, verifikasi BPJPH, fatwa, sertifikat, unduh.',1,1,'2026-11-05 14:48:28.297','2026-11-05 14:48:28.297',328,48),('bee9bac7-642b-4e74-a680-8599dc122a84','aae8308e-1a8c-4495-9c44-01bee32c8f3c','escalation','Teruskan ke Pendamping PPH','Untuk kasus bahan kritis, dokumen tidak lengkap, atau pertanyaan khusus produk.',6,1,'2026-11-05 14:48:28.297','2026-11-05 14:48:28.297',48,384),('c6c48381-dad9-47fb-b3b6-25d314ff17e4','aae8308e-1a8c-4495-9c44-01bee32c8f3c','question','Apakah self declare gratis untuk UMKM?','Untuk usaha mikro dan kecil umumnya tanpa biaya sertifikasi; biaya hanya untuk layanan tambahan.',2,1,'2026-11-05 14:48:28.297','2026-11-05 14:48:28.297',608,48),('c86b68d1-a6d6-4f07-ba9e-9b849c6a55bb','aae8308e-1a8c-4495-9c44-01bee32c8f3c','question','Dokumen apa yang harus saya siapkan?','NIB, KTP, daftar produk dan bahan, alur produksi, foto kemasan, surat pernyataan.',3,1,'2026-11-05 14:48:28.297','2026-11-05 14:48:28.297',48,216),('cc761d5c-ed6b-4b5a-b17f-8fe45a528496','aae8308e-1a8c-4495-9c44-01bee32c8f3c','question','Bagaimana cara menghubungi admin KHB?','',0,1,'2026-11-05 14:48:28.297','2026-11-09 14:15:44.306',372,289),('cd580f77-7d2d-49f7-b729-2518f2cb41bd','aae8308e-1a8c-4495-9c44-01bee32c8f3c','greeting','Pesan pembuka','Assalamu\'alaikum! Saya Asisten Halal KHB. Tanya apa saja soal sertifikasi halal, legalitas usaha, atau layanan Komunitas Halal Bandung.',0,1,'2026-11-05 14:48:28.297','2026-11-05 14:48:28.297',48,48);
